import os, csv, numpy as np

THR_CSV = 'storage/shared/agents/kairos/VEN/threshold_sweep/ven_threshold_sweep.csv'
CV_CSV  = 'storage/shared/agents/kairos/VEN/cv/ven_cv_summary.csv'
OUT_DIR = 'storage/shared/agents/kairos/VEN/threshold_sweep'
os.makedirs(OUT_DIR, exist_ok=True)

def read_thr():
    rows = []
    try:
        with open(THR_CSV, 'r', encoding='utf-8') as f:
            rd = csv.DictReader(f)
            for r in rd:
                try:
                    rows.append({
                        'dist': r['dist'],
                        'seed': int(r['seed']),
                        'n': int(r['n']),
                        'thr': float(r['threshold_frac']),
                        'ridge_points': int(r['ridge_points'])
                    })
                except Exception:
                    pass
    except FileNotFoundError:
        pass
    return rows

def read_cv():
    # dist,n,seed, ..., tail_mass_r1
    rows = []
    try:
        with open(CV_CSV, 'r', encoding='utf-8') as f:
            rd = csv.DictReader(f)
            for r in rd:
                try:
                    rows.append({
                        'dist': r['dist'],
                        'seed': int(r['seed']),
                        'n': int(r['n']),
                        'tail_mass': float(r['tail_mass_r1'])
                    })
                except Exception:
                    pass
    except FileNotFoundError:
        pass
    return rows

def group_thr(rows):
    grp = {}
    for r in rows:
        key = (r['dist'], r['n'], r['seed'])
        grp.setdefault(key, []).append((r['thr'], r['ridge_points']))
    # sort by thr
    for k in grp:
        grp[k] = sorted(grp[k], key=lambda t: t[0])
    return grp

def polyfit_slope(x, y):
    # simple linear slope dy/dx
    x = np.asarray(x, dtype=float); y = np.asarray(y, dtype=float)
    if len(x) < 2 or len(y) < 2:
        return None
    # normalize ridge_points by max to compare across seeds
    ymax = np.max(y) if np.max(y) > 0 else 1.0
    y_n = y / ymax
    m, b = np.polyfit(x, y_n, 1)
    return float(m)

thr_rows = read_thr()
cv_rows  = read_cv()

# index tail_mass by (dist,n,seed)
tail_idx = {}
for r in cv_rows:
    tail_idx[(r['dist'], r['n'], r['seed'])] = r['tail_mass']

grp = group_thr(thr_rows)

# compute slopes
slope_rows = []
for key, pairs in grp.items():
    xs = [t[0] for t in pairs]
    ys = [t[1] for t in pairs]
    slope = polyfit_slope(xs, ys)
    tail = tail_idx.get(key, None)
    slope_rows.append({
        'dist': key[0], 'n': key[1], 'seed': key[2],
        'slope_dy_dthr_norm': slope,
        'tail_mass_r1': tail
    })

# write per-seed slopes
slopes_csv = os.path.join(OUT_DIR, 'tail_sensitivity_slopes.csv')
with open(slopes_csv, 'w', encoding='utf-8', newline='') as f:
    wr = csv.DictWriter(f, fieldnames=['dist','n','seed','slope_dy_dthr_norm','tail_mass_r1'])
    wr.writeheader()
    for r in slope_rows:
        wr.writerow(r)

# per-dist correlation between slope and tail_mass
def pearson_corr(x, y):
    x = np.asarray([v for v in x if v is not None], dtype=float)
    y = np.asarray([v for v in y if v is not None], dtype=float)
    if len(x) != len(y) or len(x) < 2:
        return None
    xm = x - x.mean(); ym = y - y.mean()
    denom = np.sqrt((xm**2).sum()) * np.sqrt((ym**2).sum())
    if denom == 0: return None
    return float((xm*ym).sum() / denom)

corr_txt = os.path.join(OUT_DIR, 'tail_sensitivity_correlation.txt')
with open(corr_txt, 'w', encoding='utf-8') as f:
    f.write("Tail Sensitivity: slope(d ridge_points_norm / d threshold) vs tail_mass_r1\n")
    dists = sorted(set(r['dist'] for r in slope_rows))
    for d in dists:
        sub = [r for r in slope_rows if r['dist'] == d]
        slopes = [r['slope_dy_dthr_norm'] for r in sub if r['slope_dy_dthr_norm'] is not None]
        tails  = [r['tail_mass_r1'] for r in sub if r['slope_dy_dthr_norm'] is not None]
        corr = pearson_corr(slopes, tails)
        f.write(f"- {d}: corr={corr}\n")

print(f"[artifacts] {slopes_csv} | {corr_txt}")
